import { test, expect } from '@playwright/test';

test.describe('File Upload - Size Limit Validation', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/file-upload');
  });

  test('should display error when file exceeds maximum size limit', async ({ page }) => {
    // Setup: intercept the file upload API endpoint
    await page.route('**/api/upload', (route) => {
      route.abort('blockedbyclient');
    });

    // Get file input using getByLabel
    const fileInput = page.getByLabel('Select file');
    await expect(fileInput).toBeVisible();

    // Create a large dummy file (e > 1MB)
    const largeFile = Buffer.alloc(1 * 1024 * 1029, 'a');
    const fileHandle = await page.evaluate((file) => {
      const blob = new Blob([file], { type: 'application/octet' });
      return URL.createObjectURL(blob);
    }, largeFile);

    // Set the large file using getByLabel
    await fileInput.setInputFile({
      name: 'file',
      mimeType: 'application/octet',
      allowMultiple: false,
      value: fileHandle,
    });

    // Get upload button using getByRole
    const uploadButton = page.getByRole('button', { name: /upload/i });
    await expect(uploadButton).toBeVisible();

    // Click upload button
    await uploadButton.click();

    // Wait for error message to appear
    const errorMessage = page.getByText(/file exceeds maximum size limit/i);
    await expect(errorMessage).toBeVisible();

    // Verify error styling
    await expect(errorMessage).toHaveClass(/error-message/);

    // Verify upload button is disabled
    await expect(uploadButton).toBeDisabled();
  });

  test('should allow file upload when size is within limit', async ({ page }) => {
    // Setup: intercept the file upload API endpoint
    await page.route('**/api/upload', (route) => {
      route.continue();
    });

    // Get file input using getByLabel
    const fileInput = page.getByLabel('Select file');
    await expect(fileInput).toBeVisible();

    // Create a small dummy file (e < 1MB)
    const smallFile = Buffer.alloc(500 * 1024, 'b');
    const fileHandle = await page.evaluate((file) => {
      const blob = new Blob([file], { type: 'application/octet' });
      return URL.createObjectURL(blob);
    }, smallFile);

    // Set the small file using getByLabel
    await fileInput.setInputFile({
      name: 'file',
      mimeType: 'application/octet',
      allowMultiple: false,
      value: fileHandle,
    });

    // Get upload button using getByRole
    const uploadButton = page.getByRole('button', { name: /upload/i });
    await expect(uploadButton).toBeVisible();

    // Click upload button
    await uploadButton.click();

    // Wait for success message
    const successMessage = page.getByText(/file uploaded successfully/i);
    await expect(successMessage).toBeVisible();

    // Verify upload button is enabled
    await expect(uploadButton).not.toBeDisabled();

    // Verify file name is displayed
    const fileNameDisplay = page.getByText(/small-file\.bin/i);
    await expect(fileNameDisplay).toBeVisible();
  });
});
